public static @Nullable String getCodecsOfType(String codecs, int trackType) {
  try {
    String[] codecArray = splitCodecs(codecs);
    if (codecArray.length == 0) {
      return null;
    }
    StringBuilder builder = new StringBuilder();
    for (String codec : codecArray) {
      if (trackType == MimeTypes.getTrackTypeOfCodec(codec)) {
        if (builder.length() > 0) {
          builder.append(",");
        }
        builder.append(codec);
      }
    }
    return builder.length() > 0 ? builder.toString() : null;
  } catch (java.util.regex.PatternSyntaxException | java.lang.IndexOutOfBoundsException e) {
    // Handle the exception, e.g., log the error or return a default value
    return null;
  }
}
